#define _GNU_SOURCE

#include <dlfcn.h>
#include <errno.h>
#include <stddef.h>
#include <string.h>
#include <unistd.h>

extern char *program_invocation_short_name;

typedef ssize_t (*readlink_fn)(const char *, char *, size_t);

ssize_t readlink(const char *path, char *buffer, size_t size) {
    static readlink_fn real_readlink = NULL;
    static const char toolchain_bin[] =
        "/opt/elan/toolchains/leanprover--lean4---v4.22.0/bin/";

    if (real_readlink == NULL) {
        real_readlink = (readlink_fn)dlsym(RTLD_NEXT, "readlink");
    }

    if (path != NULL && strcmp(path, "/proc/self/exe") == 0 &&
        program_invocation_short_name != NULL &&
        (strcmp(program_invocation_short_name, "lean") == 0 ||
         strcmp(program_invocation_short_name, "lake") == 0 ||
         strcmp(program_invocation_short_name, "leanc") == 0)) {
        char resolved[512];
        size_t prefix_len = strlen(toolchain_bin);
        size_t name_len = strlen(program_invocation_short_name);
        size_t total = prefix_len + name_len;

        if (total > sizeof(resolved) || size < total) {
            errno = ENAMETOOLONG;
            return -1;
        }
        memcpy(resolved, toolchain_bin, prefix_len);
        memcpy(resolved + prefix_len, program_invocation_short_name, name_len);
        memcpy(buffer, resolved, total);
        return (ssize_t)total;
    }

    if (real_readlink == NULL) {
        errno = ENOSYS;
        return -1;
    }
    return real_readlink(path, buffer, size);
}

